#!/usr/bin/env bash
# Stands up a throwaway broker with the prod listener/authorizer layout, then
# runs the ACL provisioning and verification scripts against it.
#
#   scripts/kafka-acl-ci.sh
#
# This exists because GitHub `services:` cannot bind-mount the JKS keystore and
# JAAS file the Kafka image needs. The broker below is a plain `docker run` with
# the same flags docker-compose.prod.yml uses, so a listener or ACL regression
# fails here instead of after deploy.
#
# Needs: docker, the repo's backend/kafka/tls/ (generated by
# scripts/gen-kafka-tls-certs.ps1; in CI, generated here with keytool).
set -euo pipefail

# Git Bash on Windows rewrites /d/... paths into D:\... and breaks -v mounts
# unless this is set. Harmless on Linux/macOS runners.
export MSYS_NO_PATHCONV=1

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
NAME="goshop-acl-ci"
TLS="$ROOT/backend/kafka/tls"

cleanup() { docker rm -f "$NAME" >/dev/null 2>&1 || true; }
trap cleanup EXIT

# Passwords the verification reads from the broker's environment, exactly like
# prod (compose passes backend/.env through env_file). Fixed, non-secret values:
# the broker lives for one CI run and is not published outside the runner.
declare -A PW=(
  [admin]=ci-admin-password [broker]=broker-internal
  [order]=ci-order-password [payment]=ci-payment-password
  [identity]=ci-identity-password [inventory]=ci-inventory-password
  [catalog]=ci-catalog-password [coupon]=ci-coupon-password
  [cart]=ci-cart-password [banner]=ci-banner-password
  [review]=ci-review-password [analytics]=ci-analytics-password
  [chat]=ci-chat-password [media]=ci-media-password
  [worker]=ci-worker-password [notification]=ci-notification-password
  [api]=ci-api-password [wsgateway]=ci-wsgateway-password
)

echo "==> TLS material in $TLS"
if [ ! -f "$TLS/kafka.keystore.jks" ]; then
  bash "$ROOT/scripts/kafka-tls-certs-ci.sh"
fi

echo "==> Starting broker"
cleanup
docker run -d --name "$NAME" \
  -v "$TLS:/etc/kafka/secrets:ro" \
  -v "$TLS:/etc/kafka/tls:ro" \
  -v "$ROOT/backend/kafka/kafka_server_jaas.conf:/etc/kafka/kafka_server_jaas.conf:ro" \
  -e KAFKA_NODE_ID=1 \
  -e KAFKA_PROCESS_ROLES=broker,controller \
  -e KAFKA_CONTROLLER_QUORUM_VOTERS=1@localhost:9093 \
  -e KAFKA_CONTROLLER_LISTENER_NAMES=CONTROLLER \
  -e KAFKA_INTER_BROKER_LISTENER_NAME=BOOTSTRAP \
  -e CLUSTER_ID=goshop-acl-ci-kafka-0000001 \
  -e KAFKA_LISTENERS=SASL://0.0.0.0:29092,CONTROLLER://0.0.0.0:9093,BOOTSTRAP://0.0.0.0:29093,SASL_SSL://0.0.0.0:29096 \
  -e KAFKA_ADVERTISED_LISTENERS=SASL://localhost:29092,SASL_SSL://localhost:29096,CONTROLLER://localhost:9093,BOOTSTRAP://localhost:29093 \
  -e KAFKA_LISTENER_SECURITY_PROTOCOL_MAP=CONTROLLER:PLAINTEXT,SASL:SASL_PLAINTEXT,BOOTSTRAP:PLAINTEXT,SASL_SSL:SASL_SSL \
  -e KAFKA_SASL_ENABLED_MECHANISMS=SCRAM-SHA-512 \
  -e KAFKA_OPTS=-Djava.security.auth.login.config=/etc/kafka/kafka_server_jaas.conf \
  -e "KAFKA_SUPER_USERS=User:admin;User:broker;User:ANONYMOUS" \
  -e KAFKA_AUTHORIZER_CLASS_NAME=org.apache.kafka.metadata.authorizer.StandardAuthorizer \
  -e KAFKA_ALLOW_EVERYONE_IF_NO_ACL_FOUND=false \
  -e KAFKA_SSL_KEYSTORE_TYPE=JKS \
  -e KAFKA_SSL_KEYSTORE_FILENAME=kafka.keystore.jks \
  -e KAFKA_SSL_KEY_CREDENTIALS=key.creds \
  -e KAFKA_SSL_KEYSTORE_CREDENTIALS=store.creds \
  -e KAFKA_SSL_TRUSTSTORE_TYPE=JKS \
  -e KAFKA_SSL_TRUSTSTORE_LOCATION=/etc/kafka/tls/kafka.truststore.jks \
  -e KAFKA_SSL_TRUSTSTORE_PASSWORD=changeit \
  -e KAFKA_SSL_CLIENT_AUTH=none \
  -e KAFKA_OFFSETS_TOPIC_REPLICATION_FACTOR=1 \
  -e KAFKA_AUTO_CREATE_TOPICS_ENABLE=false \
  -e KAFKA_HEAP_OPTS="-Xmx512m -Xms256m" \
  apache/kafka:3.9.0 >/dev/null

# The user passwords reach kafka-acl-verify.sh through the exec environment
# below, mirroring prod where compose passes backend/.env into the container.

echo "==> Waiting for the broker"
for _ in $(seq 1 60); do
  if docker exec "$NAME" /opt/kafka/bin/kafka-broker-api-versions.sh \
      --bootstrap-server localhost:29093 >/dev/null 2>&1; then
    break
  fi
  sleep 2
done
docker exec "$NAME" /opt/kafka/bin/kafka-broker-api-versions.sh \
  --bootstrap-server localhost:29093 >/dev/null

echo "==> Creating SCRAM users"
for u in "${!PW[@]}"; do
  docker exec "$NAME" /opt/kafka/bin/kafka-configs.sh \
    --bootstrap-server localhost:29093 --alter \
    --entity-type users --entity-name "$u" \
    --add-config "SCRAM-SHA-512=[password=${PW[$u]}]" >/dev/null
done

echo "==> Creating ACLs"
# piped in rather than docker cp: on Git Bash, docker cp rewrites the container
# side /tmp/x.sh into D:\tmp\x.sh even with MSYS_NO_PATHCONV set.
docker exec -i "$NAME" sh -c 'cat > /tmp/kafka-acls.sh' < "$ROOT/scripts/kafka-acls.sh"
docker exec "$NAME" sh /tmp/kafka-acls.sh localhost:29093

echo "==> Verifying enforcement"
docker exec -i "$NAME" sh -c 'cat > /tmp/kafka-acl-verify.sh' < "$ROOT/scripts/kafka-acl-verify.sh"
# The verify script reads KAFKA_SASL_<USER>_PASSWORD from its own environment,
# so pass the same map in the exec, mirroring the prod env_file.
env_args=()
for u in "${!PW[@]}"; do
  env_args+=("-e" "KAFKA_SASL_$(echo "$u" | tr 'a-z' 'A-Z')_PASSWORD=${PW[$u]}")
done
docker exec "${env_args[@]}" "$NAME" sh /tmp/kafka-acl-verify.sh localhost:29093 localhost:29096
